<?php
require_once __DIR__ . '/../api/env.php';
function admin_escape(string $value): string {return htmlspecialchars($value,ENT_QUOTES,'UTF-8');}
$expected=app_env('ADMIN_PASSWORD');$error='';
if(isset($_POST['logout'])){session_start();session_destroy();header('Location: orders.php');exit;}
session_start();
if(isset($_POST['password'])){if($expected!==''&&hash_equals($expected,(string)$_POST['password'])){session_regenerate_id(true);$_SESSION['orders_admin']=true;}else{$error='Invalid password';}}
if(!($_SESSION['orders_admin']??false)){?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Orders Admin</title></head><body><form method="post"><h1>Orders Admin</h1><label>Password <input type="password" name="password" required></label><button type="submit">Sign in</button><p><?=admin_escape($error)?></p></form></body></html><?php exit;}
require_once __DIR__ . '/../api/db.php';$pdo=db();if(isset($_POST['order_no'],$_POST['status'])&&in_array($_POST['status'],['confirmed','shipped','cancelled'],true)){$q=$pdo->prepare('UPDATE orders SET status=? WHERE order_no=?');$q->execute([$_POST['status'],$_POST['order_no']]);}$orders=$pdo->query('SELECT * FROM orders ORDER BY created_at DESC,id DESC')->fetchAll();$items=$pdo->query('SELECT order_no,name,price,qty FROM order_items ORDER BY id')->fetchAll();$map=[];foreach($items as $i)$map[$i['order_no']][]=$i;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Orders Admin</title><style>body{font:16px Arial;max-width:1000px;margin:30px auto;padding:0 16px}article{border:1px solid #ccc;padding:16px;margin:16px 0}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ddd;padding:8px;text-align:left}</style></head><body><h1>Orders</h1><form method="post"><button name="logout" value="1">Sign out</button></form><?php foreach($orders as $o):?><article><h2><?=admin_escape($o['order_no'])?> · <?=admin_escape($o['status'])?></h2><p><?=admin_escape($o['customer_name'])?> · <?=admin_escape($o['phone'])?> · <?=admin_escape($o['email'])?></p><p><?=admin_escape($o['address'].', '.$o['city'])?> · <?=admin_escape($o['payment_method'])?> · Rs. <?=number_format((int)$o['total'])?></p><table><tr><th>Item</th><th>Price</th><th>Qty</th></tr><?php foreach($map[$o['order_no']]??[] as $i):?><tr><td><?=admin_escape($i['name'])?></td><td>Rs. <?=number_format((int)$i['price'])?></td><td><?=(int)$i['qty']?></td></tr><?php endforeach;?></table><form method="post"><input type="hidden" name="order_no" value="<?=admin_escape($o['order_no'])?>"><select name="status"><option value="confirmed">confirmed</option><option value="shipped">shipped</option><option value="cancelled">cancelled</option></select><button>Update status</button></form></article><?php endforeach;?></body></html>
